<form class="card filters" method="get" data-filters><input type="hidden" name="view" value="<?=h($filters['view'])?>"><label>Buscar<input name="q" placeholder="Nome ou WhatsApp" value="<?=h($filters['q'])?>"></label>
<?php foreach(['tipo'=>['Cadastro',['parcial'=>'Parciais','enviado'=>'Enviados']],'stage'=>['Etapa',$stages],'segmento'=>['Segmento',$segments],'turno'=>['Turno',$shifts]] as $key=>[$label,$items]): ?><label><?=h($label)?><select name="<?=h($key)?>"><option value="">Todos</option><?php optionList($items,$filters[$key])?></select></label><?php endforeach ?>
<label>Responsável<select name="owner"><option value="">Todos</option><?php foreach($staff as $person): ?><option value="<?=h($person['email'])?>" <?=$filters['owner']===$person['email']?'selected':''?>><?=h($person['name'])?></option><?php endforeach ?></select></label><label><?=$filters['view']==='agenda'?'Visitas desde':'Recebidos desde'?><input type="date" name="from" value="<?=h($filters['from'])?>"></label><label>Até<input type="date" name="to" value="<?=h($filters['to'])?>"></label><label>Retornos<select name="due"><option value="">Todos</option><?php optionList(['1'=>'Atrasados'],$filters['due'])?></select></label><div class="actions"><button>Aplicar filtros</button><a href="/admin/">Limpar</a></div></form>
<section class="card table"><p><strong><?=$count?></strong> contato(s) com os filtros selecionados</p><table><thead><tr><th>Contato</th><th>Interesse</th><th>Etapa e cadastro</th><th>Próximo retorno</th><th>Visita</th><th>Responsável</th></tr></thead><tbody><?php foreach($rows as $row): $late=$row['next_contact'] && strtotime($row['next_contact'].' UTC')<time() && !in_array($row['atendimento'],['matriculado','desistencia'],true); ?><tr><td><a class="contact" href="/admin/?lead=<?=h($row['id'])?>"><?=h($row['nome']?:'Nome não informado')?></a><small><?=h($row['whatsapp'])?></small><small>Recebido <?=h(dateLocal($row['created_at']))?></small></td><td><?=h($segments[$row['segmento']]??'Não informado')?><small><?=h($shifts[$row['turno']]??'')?></small></td><td><span class="badge"><?=h($stages[$row['atendimento']]??$row['atendimento'])?></span><small><?=$row['submitted']?'Enviado':'Parcial'?></small></td><td class="<?=$late?'late':''?>"><?=h(dateLocal($row['next_contact'])?:'Não definido')?><?php if($late): ?><small>Retorno atrasado</small><?php endif ?></td><td><?=h(dateLocal($row['visit_at'])?:'Não agendada')?><small><?=h($row['visit_at']?($visits[$row['visit_status']]??''):'')?></small></td><td><?=h($row['owner_email']?:'Sem responsável')?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><div class="empty"><h3>Nenhum registro encontrado</h3><p>Os registros aparecerão conforme novos contatos e visitas forem cadastrados. Ajuste os filtros para ampliar a busca.</p></div><?php endif ?><nav class="pagination" aria-label="Paginação"><?php if($page>1): ?><a href="<?=h(linkTo(['page'=>$page-1]))?>">← Anterior</a><?php endif ?><span>Página <?=$page?></span><?php if($page*30<$count): ?><a href="<?=h(linkTo(['page'=>$page+1]))?>">Próxima →</a><?php endif ?></nav></section>
<?php endif; endif ?></main><footer>Escola Montessori · Secretaria de matrículas</footer></body></html>
